def last_n(xs, n):
    # BUG: off-by-one — slices from -n+1, dropping one element.
    return xs[-n + 1:]

def summarize(rows):
    by = {}
    for r in rows:
        by[r['region']] = by.get(r['region'], 0.0) + r['units'] * r['unit_price']
    # BUG: max() on ties returns an arbitrary region, not the alphabetically-first one,
    # and it raises ValueError on empty input instead of returning None.
    top = max(by, key=by.get)
    return {'total_revenue': sum(by.values()), 'by_region': by, 'top_region': top}

def mean(xs):
    # BUG: no empty-list guard -> ZeroDivisionError on mean([]).
    return sum(xs) / len(xs)

def dedupe(xs):
    seen = set()
    # BUG: mutates the caller's list in place while iterating (also risks skipping elements).
    i = 0
    while i < len(xs):
        if xs[i] in seen:
            xs.pop(i)
        else:
            seen.add(xs[i])
            i += 1
    return xs

def last_n(xs, n):
    if n <= 0:
        return []
    return xs[-n:]

def summarize(rows):
    by = {}
    for r in rows:
        by[r['region']] = by.get(r['region'], 0.0) + r['units'] * r['unit_price']
    top = None
    if by:
        # max revenue, ties broken alphabetically by region name
        top = min(by, key=lambda region: (-by[region], region))
    return {'total_revenue': sum(by.values()), 'by_region': by, 'top_region': top}

def mean(xs):
    if not xs:
        return 0.0
    return sum(xs) / len(xs)

def dedupe(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out
